*{box-sizing:border-box} :root{--bg:#07100f;--panel:#0d1917;--panel2:#101f1c;--line:#1e3430;--muted:#77918a;--text:#e5f1ed;--mint:#9dffbd;--acid:#bdff66;--orange:#ffb666;--red:#ff6677;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:var(--sans)}body{min-height:100vh;background-image:radial-gradient(ellipse at 50% -30%,#18352c 0,transparent 58%),linear-gradient(90deg,rgba(41,76,65,.045) 1px,transparent 1px),linear-gradient(rgba(41,76,65,.04) 1px,transparent 1px);background-size:auto,36px 36px,36px 36px}.app-shell{max-width:1450px;margin:auto;padding:0 40px 32px}.topbar{height:74px;border-bottom:1px solid #1b302c;display:flex;align-items:center;justify-content:space-between;font-family:var(--mono);font-size:11px;letter-spacing:.08em}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#edfff5;font-size:15px;font-weight:700;letter-spacing:.12em}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid #61be88;border-radius:10px;color:var(--mint);font-size:19px;box-shadow:inset 0 0 16px #75ffb41a}.brand-mark span{color:var(--acid)}.brand-dim{color:#77918a;font-weight:500}.top-center{display:flex;gap:10px;align-items:center;color:#8aa39b}.live-dot,.board-live{width:7px;height:7px;border-radius:50%;background:var(--mint);display:inline-block;box-shadow:0 0 10px #9dffbd8c}.top-divider{color:#3f5b52}.wallet{color:var(--acid);font-size:14px;font-weight:500}.wallet-icon{font-size:20px;margin-right:8px}.layout{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(310px,.86fr);gap:22px;padding-top:27px}.game-column,.side-column{min-width:0}.mission-head{display:flex;justify-content:space-between;align-items:flex-start;margin:0 0 20px}.eyebrow,.tiny-label{font-family:var(--mono);font-size:9px;letter-spacing:.14em;color:#78918a}.eyebrow{display:flex;gap:8px;align-items:center;color:var(--mint);margin-bottom:8px}.tag-separator{color:#57736a}.eyebrow span:last-child{color:#93ad9f}.mission-head h1{font-size:30px;line-height:1.05;letter-spacing:-.04em;margin:0 0 7px;font-weight:600}.mission-head p{margin:0;color:#9bb0a9;font-size:13px}.timer-box{width:117px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:#0d1917;text-align:right}.timer-box .tiny-label{display:block;font-size:8px}.timer-box strong{font-family:var(--mono);font-size:18px;display:block;margin:4px 0 8px;color:var(--acid)}.timer-bar{height:3px;display:block;background:#263a33;border-radius:4px;overflow:hidden}.timer-bar i{display:block;width:100%;height:100%;background:var(--acid);transition:width .5s linear}.target-strip{height:66px;background:linear-gradient(100deg,#13231e,#0d1917);border:1px solid #263d34;border-radius:8px;display:flex;align-items:center;padding:0 16px;margin-bottom:12px;gap:13px}.target-icon{display:grid;place-items:center;width:34px;height:34px;background:#1a3125;border:1px solid #315b3c;color:var(--acid);font-size:22px;border-radius:7px}.target-info{display:flex;flex-direction:column;gap:4px;min-width:0}.target-info strong{font:500 11px var(--mono);letter-spacing:.04em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.target-reward{margin-left:auto;text-align:right;display:flex;flex-direction:column;gap:3px}.target-reward strong{font:500 14px var(--mono);color:var(--acid)}.target-reward small{font-size:9px;color:#81978e}.board-wrap{border:1px solid #294138;background:#0b1715;border-radius:8px;overflow:hidden}.board-top{height:40px;padding:0 13px;display:flex;align-items:center;gap:9px;border-bottom:1px solid #20352f;font:9px var(--mono);letter-spacing:.1em;color:var(--mint)}.board-hint{margin-left:auto;color:#718a82;letter-spacing:0;font:10px var(--sans)}.icon-btn{border:0;background:transparent;color:#89a49a;font-size:20px;padding:2px 4px;cursor:pointer}.icon-btn:hover{color:var(--mint)}.network-board{position:relative;height:330px;overflow:hidden;background:radial-gradient(ellipse at 48% 52%,#11221d 0,transparent 67%),linear-gradient(90deg,rgba(83,137,109,.045) 1px,transparent 1px),linear-gradient(rgba(83,137,109,.045) 1px,transparent 1px);background-size:auto,26px 26px,26px 26px}.edges{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.edge{stroke:#29443a;stroke-width:1.6;stroke-dasharray:4 5;opacity:.8;transition:all .2s}.edge.available{stroke:#6bb386;stroke-dasharray:2 4;opacity:.8}.edge.route{stroke:#a8ffae;stroke-width:2.5;stroke-dasharray:none;opacity:1;filter:drop-shadow(0 0 4px #a5ffad7c)}.edge.failed{stroke:#ff6575;opacity:.8}.node{position:absolute;transform:translate(-50%,-50%);width:73px;min-height:55px;border:1px solid #3c574c;border-radius:8px;background:#12211e;color:#b9ccc3;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;cursor:pointer;transition:transform .16s,border-color .16s,background .16s,box-shadow .16s;padding:6px 4px;font-family:var(--mono);-webkit-tap-highlight-color:transparent;touch-action:manipulation}.node:hover{transform:translate(-50%,-50%) scale(1.05);border-color:#8adc9a}.node .node-icon{font-size:16px;line-height:18px}.node .node-name{font-size:8px;letter-spacing:.06em;white-space:nowrap}.node .node-kind{font-size:7px;color:#708980;letter-spacing:.1em}.node.entry{border-color:#57bd89;background:#123328;color:#b8ffd2;box-shadow:0 0 18px #3de69b18}.node.objective{border-color:#c4ed61;background:#283319;color:#e1ff9f;box-shadow:0 0 18px #c5ff611c}.node.firewall{border-color:#996a48;background:#2d2119;color:#ffc581}.node.decoy{border-color:#5a536d;background:#211e2c;color:#c1b6ff}.node.selected{outline:2px solid #a8ffae;outline-offset:3px;box-shadow:0 0 20px #92ffad33}.node.visited{border-color:#85db9b}.node.next-option{animation:nodePulse 1.5s infinite;border-color:#9affad;box-shadow:0 0 15px #8aff9f2b}.node.disabled-node{opacity:.42}.node.current{background:#23452c}.node.burned{border-color:#ff6575!important;color:#ff9ea8!important;box-shadow:0 0 20px #ff65752c}.board-scan{position:absolute;z-index:1;left:0;right:0;height:24px;top:-30px;background:linear-gradient(transparent,#54cc7b10,transparent);animation:scan 8s linear infinite;pointer-events:none}.board-corner{position:absolute;width:11px;height:11px;border-color:#69947a;opacity:.5}.corner-tl{top:8px;left:8px;border-top:1px solid;border-left:1px solid}.corner-br{right:8px;bottom:8px;border-right:1px solid;border-bottom:1px solid}.board-legend{height:31px;border-top:1px solid #20352f;display:flex;align-items:center;gap:14px;padding:0 13px;color:#7e948b;font:8px var(--mono);letter-spacing:.06em}.board-legend span{display:flex;align-items:center;gap:5px}.legend-dot{width:6px;height:6px;border-radius:50%;display:inline-block;background:#8b9b93}.legend-dot.entry{background:#66df9c}.legend-dot.relay{background:#6eae8b}.legend-dot.firewall{background:#db9b5b}.legend-dot.objective{background:#c9f768}.legend-route{margin-left:auto}.legend-route i{width:13px;height:2px;background:#a8ffae;display:inline-block}.route-card{margin-top:12px;background:#0e1a17;border:1px solid #263d34;border-radius:8px;padding:13px 15px}.route-head{display:flex;justify-content:space-between;align-items:center}.route-head>div:first-child{display:flex;flex-direction:column;gap:4px}.route-head strong{font-size:12px;font-weight:500}.route-score{text-align:right}.route-score strong{font:500 14px var(--mono);color:var(--mint)}.route-chips{min-height:37px;display:flex;align-items:center;gap:6px;flex-wrap:wrap;border-bottom:1px solid #243731;padding:7px 0}.route-empty{font-size:10px;color:#71877f}.route-chip{font:9px var(--mono);padding:5px 7px;background:#172b22;border:1px solid #34523d;border-radius:4px;color:#c7f5cb}.route-arrow{color:#648171;font-size:10px}.route-footer{display:flex;align-items:center;justify-content:space-between;padding-top:10px;gap:12px;font-size:10px;color:#839890}.execute-btn,.next-btn{border:0;border-radius:5px;background:var(--acid);color:#142014;font:700 10px var(--mono);letter-spacing:.05em;padding:11px 14px;cursor:pointer;display:flex;gap:16px;align-items:center;white-space:nowrap;transition:transform .15s,filter .15s}.execute-btn:hover:not(:disabled),.next-btn:hover{filter:brightness(1.08);transform:translateY(-1px)}.execute-btn:disabled{background:#263830;color:#637c70;cursor:not-allowed}.side-column{display:flex;flex-direction:column;gap:12px}.side-card{background:linear-gradient(135deg,#10201c,#0c1715);border:1px solid #203831;border-radius:8px;padding:16px}.section-heading{display:flex;align-items:center;gap:10px}.section-icon{width:29px;height:29px;display:grid;place-items:center;border:1px solid #355340;background:#192a21;border-radius:6px;color:var(--mint);font-size:17px}.section-heading .tiny-label{font-size:8px}.section-heading h2{margin:3px 0 0;font-weight:500;font-size:14px;letter-spacing:-.02em}.objective-list{margin:17px 0 13px;display:flex;flex-direction:column;gap:11px}.objective{display:flex;align-items:center;gap:9px;color:#a8b9b1;font-size:11px}.check{width:15px;height:15px;border:1px solid #52675d;border-radius:50%;display:grid;place-items:center;font-size:9px;color:#8dffae;flex:none}.objective.done .check{border-color:#81e7a3;background:#1d3d2c}.objective.done span:last-child{color:#80a790;text-decoration:line-through}.intel-note{border-top:1px solid #223831;padding-top:11px;display:flex;gap:8px;color:#8ca198;font-size:10px;line-height:1.45}.intel-note>span{display:grid;place-items:center;border:1px solid #57705d;color:var(--acid);font:10px var(--mono);width:15px;height:15px;border-radius:50%;flex:none}.intel-note p{margin:0}.status-pill{margin-left:auto;color:#a4f5b7;background:#1a3426;border:1px solid #35563c;border-radius:10px;padding:4px 7px;font:8px var(--mono);letter-spacing:.08em}.stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:17px 0 15px}.stat-grid>div{display:flex;flex-direction:column;gap:6px}.stat-grid .tiny-label{font-size:8px}.stat-grid strong{font:500 14px var(--mono);color:#d7e8df}.stat-grid strong small{font-size:9px;color:#8ca197}.stat-grid #heat{color:var(--orange)}.stat-grid #heat span{font-size:10px}.micro-progress{height:3px;background:#293b33;border-radius:3px;overflow:hidden}.micro-progress i{height:100%;width:18%;display:block;background:#9cffae}.heat-progress i{background:var(--orange);transition:width .3s}.upgrade-row{display:flex;align-items:center;gap:9px;border-top:1px solid #253a32;padding-top:12px}.upgrade-symbol{width:28px;height:28px;display:grid;place-items:center;background:#27331d;border:1px solid #59683e;border-radius:6px;color:var(--acid);font-size:15px}.upgrade-copy{display:flex;flex-direction:column;gap:3px;min-width:0}.upgrade-copy strong{font-size:10px;font-weight:500}.upgrade-copy span{font-size:8px;color:#82978d}.upgrade-btn{margin-left:auto;white-space:nowrap;background:#25321f;color:#d4fc8d;border:1px solid #50603a;border-radius:4px;font:9px var(--mono);padding:7px;cursor:pointer}.upgrade-btn:disabled{opacity:.55;cursor:default}.log-card{flex:1;min-height:181px}.log-header{display:flex;align-items:center;justify-content:space-between}.text-btn{background:transparent;border:0;color:#637e72;font:8px var(--mono);cursor:pointer}.log-list{display:flex;flex-direction:column;gap:0;margin-top:12px}.log-entry{display:flex;gap:8px;padding:8px 0;border-top:1px solid #1e302a;font-size:9px;color:#9aaea4;line-height:1.35}.log-time{font:8px var(--mono);color:#5f796d;white-space:nowrap}.log-entry strong{font-weight:500;color:#d7e8dd}.log-entry .log-good{color:var(--mint)}.log-entry .log-warn{color:var(--orange)}.log-entry .log-bad{color:var(--red)}.footer-note{text-align:center;color:#4f695f;font:8px var(--mono);letter-spacing:.08em;padding:3px}.lock{color:#769584}.footer-dot{color:#9eae61}.modal-backdrop{position:fixed;inset:0;background:#030806c9;z-index:10;display:grid;place-items:center;padding:20px;backdrop-filter:blur(5px)}.modal-backdrop[hidden]{display:none}.result-modal{position:relative;width:min(410px,100%);background:linear-gradient(145deg,#172820,#0d1815);border:1px solid #527253;border-radius:12px;padding:30px;text-align:center;box-shadow:0 20px 80px #0009}.modal-close{position:absolute;right:14px;top:10px;background:none;border:0;color:#82978e;font-size:23px;cursor:pointer}.result-emblem{display:grid;place-items:center;width:50px;height:50px;margin:0 auto 15px;border:1px solid #7ccf8b;border-radius:50%;color:var(--acid);font-size:24px;background:#1b3322}.result-modal .tiny-label{color:var(--mint)}.result-modal h2{font-size:24px;margin:7px 0}.result-modal p{font-size:12px;color:#9eb0a7;line-height:1.6;margin:0 auto 18px;max-width:320px}.result-stats{display:grid;grid-template-columns:1fr 1fr;border:1px solid #2a4134;border-radius:7px;margin:0 0 18px}.result-stats>div{padding:12px;display:flex;flex-direction:column;gap:5px}.result-stats>div+div{border-left:1px solid #2a4134}.result-stats .tiny-label{font-size:8px;color:#82998d}.result-stats strong{font:500 15px var(--mono);color:var(--acid)}.next-btn{width:100%;justify-content:center;font-size:11px;padding:13px}.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#20372a;border:1px solid #5a865b;color:#d9ffdb;padding:10px 16px;border-radius:5px;font:10px var(--mono);z-index:20;transition:.25s}.toast.show{transform:translate(-50%,0);opacity:1}@keyframes scan{to{top:110%}}@keyframes nodePulse{50%{box-shadow:0 0 20px #8aff9f45}}
@media(max-width:980px){.app-shell{padding:0 22px 24px}.layout{grid-template-columns:minmax(0,1.45fr) minmax(275px,.85fr);gap:14px}.network-board{height:300px}.board-legend{gap:9px}.side-card{padding:13px}.mission-head h1{font-size:26px}}
@media(max-width:720px){.app-shell{padding:0 14px calc(18px + env(safe-area-inset-bottom))}.topbar{height:58px}.brand{font-size:13px}.brand-mark{width:29px;height:29px}.top-center{font-size:0}.top-center .live-dot{font-size:initial}.top-center #clock{font-size:10px}.top-center .top-divider{font-size:10px}.wallet{font-size:12px}.wallet-icon{font-size:17px;margin-right:4px}.layout{grid-template-columns:1fr;gap:13px;padding-top:19px}.mission-head{margin-bottom:14px}.mission-head h1{font-size:25px}.mission-head p{font-size:11px;max-width:245px;line-height:1.4}.timer-box{width:98px;padding:8px}.timer-box strong{font-size:16px}.target-strip{height:59px;padding:0 11px;gap:9px}.target-info strong{font-size:9px}.target-reward strong{font-size:12px}.target-reward small{display:block;font-size:8px}.board-top{height:37px;padding:0 10px}.board-hint{font-size:9px}.network-board{height:clamp(245px,70vw,340px)}.node{width:66px;min-height:52px}.board-legend{gap:8px;height:29px;padding:0 8px;font-size:7px}.board-legend span{gap:4px}.legend-route{display:none!important}.route-card{padding:11px}.route-footer{align-items:flex-start;flex-direction:column}.route-footer>span{line-height:1.4}.execute-btn{width:100%;justify-content:center;padding:12px}.side-column{gap:10px}.side-card{padding:13px}.log-card{min-height:140px}.footer-note{padding:7px}.objective-list{margin:13px 0;gap:10px}}
@media(max-width:390px){.app-shell{padding-left:10px;padding-right:10px}.board-legend{gap:6px;font-size:6.5px}.node{width:59px}.node .node-name{font-size:7px}.mission-head h1{font-size:23px}.target-reward small{display:none}}

const $ = (id) => document.getElementById(id);
const missions = [
  { title:'Ghost in the Grid', description:'Slip into a private archive and extract a ledger fragment.', target:'NORTHSTAR // ARCHIVE-7', base:840, time:102, difficulty:'LOW EXPOSURE', checkpoint:'Relay-3', intel:'An exposed relay is a safer route. The firewall is optional—but it can pay off.',
    nodes:[['entry','ENTRY','entry',9,52],['relay','RELAY-3','relay',31,30],['switch','SWITCH-9','relay',31,73],['vault','ARCHIVE','objective',78,50],['cache','CACHE-4','bonus',55,15],['firewall','ICE-WALL','firewall',55,85],['decoy','GHOST-NODE','decoy',64,51]],
    edges:[['entry','relay'],['entry','switch'],['relay','cache'],['relay','vault'],['switch','firewall'],['switch','vault'],['cache','vault'],['firewall','vault'],['vault','decoy']], ideal:['entry','relay','vault'], checkpointId:'relay', objectiveId:'vault', bonusId:'cache' },
  { title:'Paper Tigers', description:'Recover an erased payroll key from a corporate mirror.', target:'KITEWORKS // PAYROLL-MIRROR', base:1260, time:92, difficulty:'GUARDED', checkpoint:'Proxy-2', intel:'The mirror sits behind an extra proxy. A cache node contains a useful route signature.',
    nodes:[['entry','ENTRY','entry',8,52],['proxy','PROXY-2','relay',27,31],['bridge','BRIDGE-6','relay',27,73],['cache','SIG-CACHE','bonus',47,17],['sentinel','SENTINEL','firewall',49,52],['ghost','GHOST-4','decoy',48,87],['mirror','PAYROLL','objective',79,52]],
    edges:[['entry','proxy'],['entry','bridge'],['proxy','cache'],['proxy','sentinel'],['bridge','sentinel'],['bridge','ghost'],['cache','mirror'],['sentinel','mirror'],['ghost','mirror']], ideal:['entry','proxy','cache','mirror'], checkpointId:'proxy', objectiveId:'mirror', bonusId:'cache' },
  { title:'Blue Hour', description:'Extract a black-box telemetry shard before the watch rotates.', target:'HELIO-DYNE // BLACKBOX-12', base:1720, time:82, difficulty:'HIGH EXPOSURE', checkpoint:'Relay-8', intel:'A direct path crosses active inspection. The quiet relay is longer, but leaves less trace.',
    nodes:[['entry','ENTRY','entry',8,52],['relay','RELAY-8','relay',27,25],['tunnel','TUNNEL-5','relay',27,76],['cache','KEYCACHE','bonus',49,14],['inspect','INSPECTOR','firewall',49,52],['decoy','MIRROR-NET','decoy',49,88],['blackbox','BLACKBOX','objective',80,52]],
    edges:[['entry','relay'],['entry','tunnel'],['relay','cache'],['relay','inspect'],['tunnel','inspect'],['tunnel','decoy'],['cache','blackbox'],['inspect','blackbox'],['decoy','blackbox']], ideal:['entry','relay','cache','blackbox'], checkpointId:'relay', objectiveId:'blackbox', bonusId:'cache' }
];
const defaults = { credits:1250, heat:12, rep:0, scrambler:0, mission:0, log:[] };
let save; try { save={...defaults,...JSON.parse(localStorage.getItem('ghostline-save')||'{}')}; } catch { save={...defaults}; }
let mission, route=[], remaining=0, tickTimer, toastTimer, operationLocked=false;
const nodeMap=()=>Object.fromEntries(mission.nodes.map(n=>[n[0],{id:n[0],name:n[1],type:n[2],x:n[3],y:n[4]}]));
function persist(){localStorage.setItem('ghostline-save',JSON.stringify(save));}
function money(n){return '₡ '+Math.max(0,Math.floor(n)).toLocaleString('en-US');}
function addLog(text,kind='') {const t=new Date().toLocaleTimeString('en-US',{hour12:false});save.log.unshift({t,text,kind});save.log=save.log.slice(0,6);renderLog();persist();}
function renderLog(){const box=$('log');box.innerHTML='';if(!save.log.length){box.innerHTML='<div class="log-entry"><span class="log-time">--:--:--</span><span>Awaiting an operation...</span></div>';return;}save.log.forEach(item=>{const row=document.createElement('div');row.className='log-entry';row.innerHTML=`<span class="log-time">${item.t}</span><span class="${item.kind}">${item.text}</span>`;box.append(row);});}
function rank(){if(save.rep>=8)return ['GHOST','04'];if(save.rep>=5)return ['PHANTOM','03'];if(save.rep>=2)return ['OPERATOR','02'];return ['NOVICE','01'];}
function renderStats(){ $('wallet').textContent=money(save.credits);$('heat').innerHTML=`${save.heat}<span>%</span>`;$('heat-fill').style.width=`${save.heat}%`;let [r,n]=rank();$('rep').innerHTML=`${r} <small>${n}</small>`;$('rep-fill').style.width=`${Math.min(100,15+save.rep*11)}%`;const cost=650+save.scrambler*500;$('upgrade').disabled=save.scrambler>=3;$('upgrade').innerHTML=save.scrambler>=3?'MAXED':`${money(cost)} <span>↗</span>`;$('upgrade-label').textContent=save.scrambler>=3?'Signal scrambler fully tuned':`Reduce trace gain · level ${save.scrambler}/3`;}
function setMission(){mission=missions[save.mission%missions.length];route=['entry'];remaining=mission.time;operationLocked=false;$('contract-tag').textContent=`CONTRACT ${String(save.mission+1).padStart(2,'0')}`;$('difficulty').textContent=mission.difficulty;$('mission-title').textContent=mission.title;$('mission-description').textContent=mission.description;$('target-name').textContent=mission.target;$('reward').innerHTML=`${money(mission.base)} <small>+ quality bonus</small>`;$('intel').textContent=mission.intel;renderBoard();renderRoute();renderObjectives();updateTimer();}
function renderBoard(){const board=$('board'),nodes=$('nodes');nodes.innerHTML='';const map=nodeMap();mission.nodes.forEach(([id,name,type,x,y])=>{const el=document.createElement('button');el.className=`node ${type}`;el.dataset.id=id;el.style.left=x+'%';el.style.top=y+'%';const icons={entry:'⌂',relay:'⟡',objective:'◈',firewall:'▧',bonus:'✳',decoy:'◇'};el.innerHTML=`<span class="node-icon">${icons[type]||'◇'}</span><span class="node-name">${name}</span><span class="node-kind">${type==='objective'?'DATA':type.toUpperCase()}</span>`;el.setAttribute('aria-label',`${name}, ${type}`);el.addEventListener('click',()=>selectNode(id));nodes.append(el);});drawEdges();window.addEventListener('resize',drawEdges,{passive:true});}
function drawEdges(){if(!mission)return;const svg=$('edges'),board=$('board'),w=board.clientWidth,h=board.clientHeight;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML='';const map=nodeMap();mission.edges.forEach(([a,b])=>{const A=map[a],B=map[b],line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',A.x*w/100);line.setAttribute('y1',A.y*h/100);line.setAttribute('x2',B.x*w/100);line.setAttribute('y2',B.y*h/100);line.classList.add('edge');const ix=route.indexOf(a),iy=route.indexOf(b);if(ix>=0&&iy>=0&&Math.abs(ix-iy)===1)line.classList.add('route');else if(route.length&&route.at(-1)===a&&isLinked(a,b)&&!route.includes(b)||route.at(-1)===b&&isLinked(b,a)&&!route.includes(a))line.classList.add('available');svg.append(line);});document.querySelectorAll('.node').forEach(el=>{const id=el.dataset.id;el.classList.toggle('visited',route.includes(id));el.classList.toggle('current',route.at(-1)===id);el.classList.toggle('next-option',route.length>0&&isLinked(route.at(-1),id)&&!route.includes(id)&&!operationLocked);el.classList.toggle('disabled-node',operationLocked);});}
function isLinked(a,b){return mission.edges.some(e=>(e[0]===a&&e[1]===b)||(e[1]===a&&e[0]===b));}
function selectNode(id){if(operationLocked)return;if(id==='entry'&&route.length===1){toast('ENTRY node is already linked. Choose a neighboring node.');return;}const last=route.at(-1);if(route.includes(id)){if(id===last){toast('That node is already at the end of your route.');return;}if(id==='entry'){resetRoute();return;}route=route.slice(0,route.indexOf(id)+1);renderBoard();renderRoute();return;}if(!isLinked(last,id)){toast('No direct connection. Choose a highlighted adjacent node.');return;}route.push(id);renderBoard();renderRoute();}
function resetRoute(){if(operationLocked)return;route=['entry'];renderBoard();renderRoute();toast('Route cleared. Start again from ENTRY.');}
function qualityScore(){const ideal=mission.ideal;let common=0;while(common<route.length&&common<ideal.length&&route[common]===ideal[common])common++;let score=74-(Math.abs(route.length-ideal.length)*7)+(common/ideal.length)*21;const types=nodeMap();route.forEach(id=>{if(types[id].type==='firewall')score-=16;if(types[id].type==='decoy')score-=14;if(types[id].type==='bonus')score+=8;if(types[id].type==='relay')score+=2;});score-=Math.max(0,route.length-ideal.length)*3;return Math.max(8,Math.min(100,Math.round(score)));}
function renderRoute(){const map=nodeMap(),quality=qualityScore(),done=route.includes(mission.objectiveId);$('route-chips').innerHTML=route.map((id,i)=>`${i?'<span class="route-arrow">→</span>':''}<span class="route-chip">${map[id].name}</span>`).join('')+(route.length===1?'<span class="route-empty">· choose a highlighted connection</span>':'');$('route-state').textContent=done?'Target reached · ready to breach':`${route.length-1} ${route.length===2?'link':'links'} connected`;$('quality').textContent=`${quality}%`;$('quality').style.color=quality>=80?'var(--mint)':quality>=55?'var(--orange)':'var(--red)';$('execute').disabled=!done||operationLocked;$('board-hint').textContent=done?'Target reached — execute when ready':`Next: connect to a highlighted node · ${route.length-1} links`;const checkpoint=route.includes(mission.checkpointId);setObj(0,checkpoint,`Pass through ${mission.checkpoint}`);setObj(1,done,`Reach ${nodeMap()[mission.objectiveId].name} data vault`);setObj(2,quality>=65,`Maintain link quality above 65%`);}
function setObj(i,done,text){const list=$('objectives');if(!list.children[i]){const e=document.createElement('div');e.className='objective';e.innerHTML='<span class="check"></span><span></span>';list.append(e);}const el=list.children[i];el.classList.toggle('done',done);el.children[0].textContent=done?'✓':'';el.children[1].textContent=text;}
function renderObjectives(){ $('objectives').innerHTML='';renderRoute(); }
function updateTimer(){const m=Math.floor(remaining/60),s=remaining%60;$('timer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;$('timer-fill').style.width=`${Math.max(0,remaining/mission.time*100)}%`;$('timer-fill').style.background=remaining<25?'var(--red)':'var(--acid)';}
function tick(){if(remaining>0){remaining--;updateTimer();}else{$('timer').textContent='00:00';}}
function runOperation(){if(operationLocked||!route.includes(mission.objectiveId))return;operationLocked=true;const quality=qualityScore(),passedCheckpoint=route.includes(mission.checkpointId),hasBonus=route.includes(mission.bonusId),firewall=route.some(id=>nodeMap()[id].type==='firewall'),decoy=route.some(id=>nodeMap()[id].type==='decoy');let risk=39+(70-quality)*.55+(firewall?16:0)+(decoy?12:0)+(save.heat*.22)-(save.scrambler*8);if(passedCheckpoint)risk-=7;if(remaining===0)risk+=14;risk=Math.max(8,Math.min(88,Math.round(risk)));const roll=Math.random()*100,success=roll>=risk;const bonus=Math.round((quality/100)*mission.base*.55)+(hasBonus?Math.round(mission.base*.18):0);let earned=success?mission.base+bonus:Math.max(0,Math.round(mission.base*.08));let title,copy,kicker;if(success){save.credits+=earned;save.rep+=quality>=75?1:0;save.heat=Math.max(0,save.heat+(firewall?17:decoy?12:8)-save.scrambler*4);title=quality>=82?'Ghost-clean extraction':'Data recovered';kicker='OPERATION COMPLETE';copy=`Payload secured from ${mission.target}. ${hasBonus?'The cache signature added a bonus. ':''}The route held at ${quality}% quality with ${risk}% estimated trace risk.`;addLog(`<strong class="log-good">PAYLOAD SECURED</strong> · ${mission.title} · +${money(earned)}`);}else{save.heat=Math.min(100,save.heat+(firewall?27:18)-save.scrambler*3);title=roll<risk*.42?'ICE caught the signal':'Extraction disrupted';kicker='OPERATION COMPROMISED';copy=`The target rejected your route. ${earned?`A partial fragment escaped for ${money(earned)}.`:'No payload recovered.'} Trace heat increased.`;addLog(`<strong class="log-warn">BREACH FLAGGED</strong> · ${mission.title} · ${risk}% trace risk`,'');}save.heat=Math.max(0,Math.min(100,save.heat));persist();renderStats();renderBoard();$('result-emblem').textContent=success?'✓':'!';$('result-emblem').style.borderColor=success?'#7ccf8b':'#df7777';$('result-emblem').style.color=success?'var(--acid)':'var(--red)';$('result-kicker').textContent=kicker;$('result-title').textContent=title;$('result-copy').textContent=copy;$('result-money').textContent=`${success?'+':''}${money(earned)}`;$('result-rating').textContent=`${quality}% · ${quality>=85?'S':quality>=72?'A':quality>=55?'B':'C'}`;$('result-rating').style.color=quality>=72?'var(--acid)':'var(--orange)';$('next-mission').textContent=save.mission%missions.length===missions.length-1?'REPLAY CONTRACTS':'NEXT CONTRACT';$('result-modal').hidden=false;}
function nextMission(){save.mission++;save.heat=Math.max(0,save.heat-5);persist();$('result-modal').hidden=true;setMission();renderStats();}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
$('execute').addEventListener('click',runOperation);$('reset-route').addEventListener('click',resetRoute);$('upgrade').addEventListener('click',()=>{if(save.scrambler>=3)return;const cost=650+save.scrambler*500;if(save.credits<cost){toast('Not enough credits for the scrambler upgrade.');return;}save.credits-=cost;save.scrambler++;addLog(`<strong class="log-good">SCRAMBLER UPGRADED</strong> · level ${save.scrambler}`);renderStats();toast('Signal scrambler upgraded. Trace reduced.');});$('next-mission').addEventListener('click',nextMission);$('modal-close').addEventListener('click',()=>{$('result-modal').hidden=true;});$('result-modal').addEventListener('click',e=>{if(e.target===$('result-modal'))$('result-modal').hidden=true;});$('clear-log').addEventListener('click',()=>{save.log=[];renderLog();persist();});
function showClock(){const d=new Date();$('clock').textContent=d.toLocaleTimeString('en-US',{hour12:false});}
renderStats();renderLog();setMission();showClock();setInterval(showClock,1000);tickTimer=setInterval(tick,1000);

