+function setMission(){const cycle=Math.floor(save.mission/missions.length);mission={...missions[save.mission%missions.length]};mission.base=Math.round(mission.base*(1+cycle*.18));mission.time=Math.max(45,mission.time-cycle*5);if(cycle)mission.difficulty+=` · LOOP ${cycle+1}`;route=['entry'];remaining=mission.time;operationLocked=false;$('contract-tag').textContent=`CONTRACT ${String(save.mission+1).padStart(2,'0')}`;$('difficulty').textContent=mission.difficulty;$('mission-title').textContent=mission.title;$('mission-description').textContent=mission.description;$('target-name').textContent=mission.target;$('reward').innerHTML=`${money(mission.base)} <small>+ quality bonus</small>`;$('intel').textContent=mission.intel;renderBoard();renderRoute();renderObjectives();updateTimer();}
 function renderBoard(){const board=$('board'),nodes=$('nodes');nodes.innerHTML='';const map=nodeMap();mission.nodes.forEach(([id,name,type,x,y])=>{const el=document.createElement('button');el.className=`node ${type}`;el.dataset.id=id;el.style.left=x+'%';el.style.top=y+'%';const icons={entry:'⌂',relay:'⟡',objective:'◈',firewall:'▧',bonus:'✳',decoy:'◇'};el.innerHTML=`<span class="node-icon">${icons[type]||'◇'}</span><span class="node-name">${name}</span><span class="node-kind">${type==='objective'?'DATA':type.toUpperCase()}</span>`;el.setAttribute('aria-label',`${name}, ${type}`);el.addEventListener('click',()=>selectNode(id));nodes.append(el);});drawEdges();window.addEventListener('resize',drawEdges,{passive:true});}
 function drawEdges(){if(!mission)return;const svg=$('edges'),board=$('board'),w=board.clientWidth,h=board.clientHeight;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML='';const map=nodeMap();mission.edges.forEach(([a,b])=>{const A=map[a],B=map[b],line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',A.x*w/100);line.setAttribute('y1',A.y*h/100);line.setAttribute('x2',B.x*w/100);line.setAttribute('y2',B.y*h/100);line.classList.add('edge');const ix=route.indexOf(a),iy=route.indexOf(b);if(ix>=0&&iy>=0&&Math.abs(ix-iy)===1)line.classList.add('route');else if(route.length&&route.at(-1)===a&&isLinked(a,b)&&!route.includes(b)||route.at(-1)===b&&isLinked(b,a)&&!route.includes(a))line.classList.add('available');svg.append(line);});document.querySelectorAll('.node').forEach(el=>{const id=el.dataset.id;el.classList.toggle('visited',route.includes(id));el.classList.toggle('current',route.at(-1)===id);el.classList.toggle('next-option',route.length>0&&isLinked(route.at(-1),id)&&!route.includes(id)&&!operationLocked);el.classList.toggle('disabled-node',operationLocked);});}
 function isLinked(a,b){return mission.edges.some(e=>(e[0]===a&&e[1]===b)||(e[1]===a&&e[0]===b));}
 function selectNode(id){if(operationLocked)return;if(id==='entry'&&route.length===1){toast('ENTRY node is already linked. Choose a neighboring node.');return;}const last=route.at(-1);if(route.includes(id)){if(id===last){toast('That node is already at the end of your route.');return;}if(id==='entry'){resetRoute();return;}route=route.slice(0,route.indexOf(id)+1);renderBoard();renderRoute();return;}if(!isLinked(last,id)){toast('No direct connection. Choose a highlighted adjacent node.');return;}route.push(id);renderBoard();renderRoute();}
